import path from 'node:path';
import { sql } from 'drizzle-orm';
import { migrate as migratePglite } from 'drizzle-orm/pglite/migrator';
import { migrate as migratePg } from 'drizzle-orm/node-postgres/migrator';
import type { DbRuntime } from './client';
import { AppError } from '../modules/errors';
import journal from '../../../drizzle/meta/_journal.json';

/**
 * Schema history lives in ./drizzle (generated by `drizzle-kit generate` from schema.ts).
 * The app NEVER applies it on a request to a real database. The owner runs `npm run db:migrate`.
 * Local PGlite outside production applies it on start-up for convenience, and tests use it too.
 */
export const MIGRATIONS_FOLDER = path.resolve(/*turbopackIgnore: true*/ process.cwd(), 'drizzle');
export const EXPECTED_MIGRATION_COUNT = journal.entries.length;

export async function applyMigrations(runtime: DbRuntime): Promise<void> {
  if (runtime.driver === 'pglite') {
    await migratePglite(runtime.db as never, { migrationsFolder: MIGRATIONS_FOLDER });
  } else {
    await migratePg(runtime.db as never, { migrationsFolder: MIGRATIONS_FOLDER });
  }
}

/** Kept for existing callers and tests. Same as applyMigrations. */
export const ensureSchema = applyMigrations;

export async function countAppliedMigrations(runtime: DbRuntime): Promise<number> {
  const res = await runtime.db.execute(
    sql`SELECT count(*)::int AS n FROM drizzle."__drizzle_migrations"`
  );
  const rows = (res as unknown as { rows: Array<{ n: number }> }).rows;
  return rows[0]?.n ?? 0;
}

/** Throws a 503 if the database does not have every migration. Does not change the database. */
export async function assertMigrated(runtime: DbRuntime): Promise<void> {
  let applied = 0;
  try {
    applied = await countAppliedMigrations(runtime);
  } catch {
    applied = 0;
  }
  if (applied < EXPECTED_MIGRATION_COUNT) {
    throw new AppError(
      503,
      'DB_NOT_MIGRATED',
      'ฐานข้อมูลยังไม่พร้อมใช้งาน กรุณาติดต่อผู้ดูแลระบบ',
      { applied, expected: EXPECTED_MIGRATION_COUNT }
    );
  }
}

/** Local PGlite outside production applies migrations. Any other database must already be migrated. */
export async function prepareSchema(runtime: DbRuntime): Promise<void> {
  if (runtime.driver === 'pglite' && process.env.NODE_ENV !== 'production') {
    await applyMigrations(runtime);
  } else {
    await assertMigrated(runtime);
  }
}
